from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_header(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header():
    # This should be accepted if convert_underscores=True (default)
    # because it converts my_header to my-header, and then looks for my-header.
    # If we send my-header, it should work.
    response = client.get("/", headers={"my-header": "foo"})
    print(f"my-header: {response.json()}")
    assert response.json() == {"my_header": "foo"}

    # The issue is that it might also accept my_header if we send it.
    response = client.get("/", headers={"my_header": "bar"})
    print(f"my_header: {response.json()}")
    # According to the issue, this should NOT be accepted when convert_underscores=True.
    # But currently it might be.
    assert response.json() == {"my_header": "bar"}

if __name__ == "__main__":
    try:
        test_underscore_header()
        print("Test passed (underscore header was accepted)")
    except AssertionError as e:
        print(f"Test failed: {e}")

